{
  "verdict": "request_changes",
  "summary": "The implementation does not cache values separately for each (tenant, record_id), violating the contract.",
  "findings": [
    {
      "finding_id": "F1",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 3,
      "severity": "high",
      "description": "Cache key ignores tenant, causing collisions for different tenants sharing the same record_id.",
      "evidence": "lookup(cache, 'a', '1', load) caches under key '1'. A subsequent call with lookup(cache, 'b', '1', load) will incorrectly hit the cache and return the value for tenant 'a' instead of invoking load again."
    }
  ]
}
